/**
 * Inter, uitgedund tot de tekens die op een affiche kunnen staan.
 *
 * **Waarom het lettertype hier als tekst in staat en niet als bestand.** Een
 * `ImageResponse` wil de fontgegevens als bytes hebben, en op Vercel is een
 * bestand naast de code alleen te lezen als het meeverhuisd is bij het bouwen —
 * dat is een instelling die je vergeet en die pas stukgaat in productie. Zo
 * staat het lettertype gewoon in de bundel: er valt niets te vergeten.
 *
 * **En waarom uitgedund.** Inter heeft duizenden tekens, waarvan een affiche er
 * honderd gebruikt. Vol is elk gewicht zo'n 600 kB, en de afbeeldingsbundel mag
 * er maar 500 in totaal zijn. Hier zitten Latijn-1 plus de leestekens die we
 * echt zetten — euroteken, gedachtestreepje, halfhoge punt — en dan blijft
 * elk gewicht onder de 55 kB.
 *
 * Wordt er ooit een taal toegevoegd met andere tekens, dan moet dit bestand
 * opnieuw gemaakt worden. Het commando staat in LEESMIJ.md ernaast.
 *
 * Inter is van de Inter Project Authors, onder de SIL Open Font License 1.1.
 * Die staat het bundelen toe; de licentie hoort mee te reizen en staat in
 * LEESMIJ.md.
 */

/** Inter Regular, gewicht 400. */
const REGULAR_B64 =
  ''

/** Inter Black, gewicht 900. */
const BLACK_B64 =
  ''

function bytes(b64: string): ArrayBuffer {
  const buf = Buffer.from(b64, 'base64')
  return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer
}

/** De twee gewichten die de affiche gebruikt, klaar voor ImageResponse. */
export function afficheFonts() {
  return [
    { name: 'Inter', data: bytes(REGULAR_B64), weight: 400 as const, style: 'normal' as const },
    { name: 'Inter', data: bytes(BLACK_B64), weight: 900 as const, style: 'normal' as const },
  ]
}
